#pragma once
#include <algorithm>
#include <array>
#include <cstdint>
#include <string_view>

namespace fssm::parse::ds2 {
    struct Area {
        int32_t mapId;
        std::string_view name;
    };

    // Generated by tools/ds2_items/gen_items.py (sorted by mapId).
    extern const std::array<Area, 54> ALL_AREAS;

    // Area name for a LoadInfoSlot::mapId; falls back to the map's base id
    // (sub areas like 10140001 share the name of 10140000).
    inline std::string_view findAreaName(int32_t mapId) {
        for (int32_t id : {mapId, mapId / 10000 * 10000}) {
            auto it = std::lower_bound(ALL_AREAS.begin(), ALL_AREAS.end(), id,
                                       [](const Area& area, int32_t value) { return area.mapId < value; });
            if (it != ALL_AREAS.end() && it->mapId == id) return it->name;
        }
        return {};
    }
}
